type ButtonType = "Create" | "Join";

interface ButtonProps {
  type: ButtonType;
}

export default function Button({ type }: ButtonProps) {
  return (
    <button
      className={`p-2 mt-5 w-50 rounded-[10px] cursor-pointer ${type === "Create" ? "bg-white text-black" : "border border-gray-500"}`}
    >
      {type === "Create" ? "Создать комнату" : "Войти по коду"}
    </button>
  );
}
